class Solution:
    def countExcellentPairs(self, nums: list[int], k: int) -> int:
        unique_nums = list(set(nums))
        bit_counts = [bin(x).count('1') for x in unique_nums]
        bit_counts.sort()
        ans = 0
        n = len(bit_counts)
        j = n - 1
        for i in range(n):
            while j >= 0 and bit_counts[i] + bit_counts[j] >= k:
                j -= 1
            ans += (n - 1 - j)
        return ans

class Solution {
public:
    long long countExcellentPairs(std::vector<int>& nums, int k) {
        std::sort(nums.begin(), nums.end());
        nums.erase(std::unique(nums.begin(), nums.end()), nums.end());
        std::vector<int> bit_counts;
        for (int x : nums) bit_counts.push_back(__builtin_popcount(x));
        std::sort(bit_counts.begin(), bit_counts.end());
        long long ans = 0;
        int n = bit_counts.size(), j = n - 1;
        for (int i = 0; i < n; ++i) {
            while (j >= 0 && bit_counts[i] + bit_counts[j] >= k) j--;
            ans += (n - 1 - j);
        }
        return ans;
    }
};

class Solution {
    public long countExcellentPairs(int[] nums, int k) {
        java.util.Set<Integer> set = new java.util.HashSet<>();
        for (int x : nums) set.add(x);
        int n = set.size(), idx = 0;
        int[] bitCounts = new int[n];
        for (int x : set) bitCounts[idx++] = Integer.bitCount(x);
        java.util.Arrays.sort(bitCounts);
        long ans = 0;
        int j = n - 1;
        for (int i = 0; i < n; ++i) {
            while (j >= 0 && bitCounts[i] + bitCounts[j] >= k) j--;
            ans += (n - 1 - j);
        }
        return ans;
    }
}

var countExcellentPairs = function(nums, k) {
    const set = new Set(nums);
    const bitCounts = [];
    for (let x of set) {
        let count = 0;
        while (x > 0) {
            count += (x & 1);
            x >>>= 1;
        }
        bitCounts.push(count);
    }
    bitCounts.sort((a, b) => a - b);
    let ans = 0, n = bitCounts.length, j = n - 1;
    for (let i = 0; i < n; ++i) {
        while (j >= 0 && bitCounts[i] + bitCounts[j] >= k) j--;
        ans += (n - 1 - j);
    }
    return ans;
};
